INSERT INTO job_vacancies (id, employer_id, job_title_id, job_category_id, employment_type_id, industry_id, job_level_id, number_of_openings, country_id, city_id, district_id, work_arrangement_id, salary_range_id, salary_type_id, benefits, responsibilities, required_qualifications, preferred_skills, additional_notes, degree_level_id, experience_level_id, status, created_at) VALUES
(1, 1, 1, 1, 1, 1, 1, 1, 1, 2, 13, 1, 1, 1, 'English / Japanese language courses subsidised, flexible working hours.', 'Mentor junior engineers and contribute to internal engineering blogs. Translate functional requirements into clean, well-tested code following the team coding standards. Participate in code reviews, sprint planning, retrospectives and on-call rotations. Own the data pipeline from ingestion to visualisation, ensuring data quality.', 'Comfort working with relational databases (MySQL, PostgreSQL) and writing SQL. Bachelor degree in Computer Science, Information Systems, or equivalent practical experience. Track record of shipping production-quality software in collaborative teams. Strong communication skills in English and Vietnamese (written and spoken).', 'Exposure to data warehousing tools (BigQuery, Snowflake, Redshift). Experience with cloud platforms (AWS, GCP or Azure).', 'You will join a 6-person squad reporting to the Engineering Manager.', 1, 1, 'active', '2026-03-31 02:00:00'),
(2, 2, 8, 4, 1, 12, 2, 1, 1, 2, 11, 2, 2, 2, 'Annual company trip, monthly team-building budget, snack-stocked pantry.', 'Own the data pipeline from ingestion to visualisation, ensuring data quality. Mentor junior engineers and contribute to internal engineering blogs. Collaborate with marketing on multi-channel campaigns and performance tracking. Participate in code reviews, sprint planning, retrospectives and on-call rotations.', 'Solid understanding of OOP, algorithms, and modern web architecture. Track record of shipping production-quality software in collaborative teams. Strong communication skills in English and Vietnamese (written and spoken). Experience working in an Agile / Scrum delivery team.', 'Open-source contributions or technical writing. A portfolio of shipped products or design case studies.', 'Visa sponsorship considered for exceptional international candidates.', 2, 2, 'active', '2026-04-11 04:00:00'),
(3, 3, 15, 7, 1, 11, 3, 3, 2, 8, 26, 3, 3, 1, 'Macbook Pro provided, fully covered training budget, hybrid work option.', 'Participate in code reviews, sprint planning, retrospectives and on-call rotations. Collaborate with marketing on multi-channel campaigns and performance tracking. Build, ship and maintain user-facing features in close collaboration with design and product. Mentor junior engineers and contribute to internal engineering blogs.', 'Bachelor degree in Computer Science, Information Systems, or equivalent practical experience. Solid understanding of OOP, algorithms, and modern web architecture. Track record of shipping production-quality software in collaborative teams. Comfort working with relational databases (MySQL, PostgreSQL) and writing SQL.', 'Knowledge of Docker, Kubernetes or other container tooling. Open-source contributions or technical writing.', 'Two technical interviews + final culture-fit conversation with the hiring manager.', 3, 3, 'active', '2026-04-28 09:00:00'),
(4, 4, 22, 10, 1, 10, 4, 2, 5, 14, 37, 1, 4, 2, 'English / Japanese language courses subsidised, flexible working hours.', 'Build, ship and maintain user-facing features in close collaboration with design and product. Mentor junior engineers and contribute to internal engineering blogs. Collaborate with marketing on multi-channel campaigns and performance tracking. Participate in code reviews, sprint planning, retrospectives and on-call rotations.', 'Track record of shipping production-quality software in collaborative teams. Experience working in an Agile / Scrum delivery team. Solid understanding of OOP, algorithms, and modern web architecture. Familiarity with REST APIs, version control (Git), and CI/CD pipelines.', 'Knowledge of Docker, Kubernetes or other container tooling. Open-source contributions or technical writing.', 'Relocation support available for candidates outside the city.', 4, 4, 'active', '2026-04-04 11:00:00'),
